"""Transform the output of databases to something more manageable.

    :param list values: The list of values from `SHOW DATABASES`
    :rtype: dict

    """
def transform_databases(values: Any) -> object {
    output = {};
    for row in values {
        if (row['name'] not in output) {
            output[row['name']] = {};
        }
        for (k, v) in row.items() {
            if (k in ['database', 'force_user', 'host', 'name', 'port', 'pool_mode']) {
                continue;
            }
            output[row['name']][k] = v;
        }
    }
    return output;
}

